/* ab92: synthetic interactions; actual OS permissions/services remain in App. */
const ab92Texts=__AUTO_BILLING_TEXTS__,ab92Fixtures=__AUTO_BILLING_FIXTURES__;
let ab92Data=null,ab92Key=null,ab92Event='',ab92Requests=[];
const ab92Copy=v=>JSON.parse(JSON.stringify(v));
function ab92Use(key){if(ab92Key!==key){ab92Data=ab92Copy(ab92Fixtures.scenes.find(s=>s.key===key)?.data||ab92Fixtures.defaults);ab92Key=key;ab92Event='';ab92Requests=[];}return ab92Render(key==='auto-billing-sample');}
function ab92Text(key,args={}){return String(ab92Texts[key]||key).replace(/\{(\w+)\}/g,(_,k)=>args[k]??'');}
function ab92Toggle(){const s=ab92Data;if(s.busy||s.loading||s.loadError)return false;if(!s.enabled&&!s.permission){ab92Event=ab92Texts.photosPermissionRequired;return false;}if(s.enabled?s.disableError:s.enableError){ab92Event=s.enabled?ab92Texts.disableFailed:ab92Texts.enableFailed;return false;}s.enabled=!s.enabled;ab92Event=s.enabled?ab92Texts.enableSuccess:ab92Texts.disableSuccess;return true;}
function ab92Open(kind){if(ab92Data.busy)return false;const url=kind==='shortcut'?ab92Fixtures.shortcutUrl:ab92Fixtures.tutorialUrl;ab92Requests.push({kind,url});ab92Event=ab92Data.openError?(kind==='shortcut'?ab92Texts.iosAutoImportFailed:ab92Texts.commonError):'已调用局部'+(kind==='shortcut'?'快捷指令导入':'视频教程')+'回调；未打开外部应用';return !ab92Data.openError;}
function ab92Button(action,label,cls='',disabled=false){return `<button data-ab92="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`;}
function ab92Info(title,description,glyph='info'){return `<article class="ab92-card"><h3>${icon(glyph)}<span>${esc(title)}</span></h3><p>${esc(description)}</p></article>`;}
function ab92Render(sample=false){
 const s=ab92Data,t=ab92Texts,ios=s.platform==='ios',busy=s.busy||s.loading;
 const heading=`<header class="ab92-header"><button data-action="back" aria-label="${esc(t.commonBack)}">${icon('chevron-left')}</button><h2>${esc(ios?t.autoScreenshotBillingIosTitle:t.autoScreenshotBillingTitle)}</h2></header>`;
 const selector=sample?`<aside class="ab92-control"><p>局部合成示例；不请求系统权限或打开快捷指令</p><div>${[['ios','iOS'],['android','Android']].map(([id,label])=>ab92Button('platform:'+id,label,s.platform===id?'selected':'')).join('')}${ios?ab92Button('old-ios',esc(t.iosVersionWarningTitle),s.oldIOS?'selected':''):''}</div></aside>`:'';
 const actionCard=(title,desc,action,label,glyph='zap')=>`<article class="ab92-card"><h3>${icon(glyph)}<span>${esc(title)}</span></h3><p>${esc(desc)}</p>${ab92Button(action,(busy?icon('loader-circle'):'')+esc(label),'ab92-primary',busy)}</article>`;
 let body;
 if(ios){body=`${ab92Button('tutorial',`<span class="ab92-visual">${icon('circle-play')}</span><span><b>${esc(t.iosAutoTutorialTitle)}</b><small>${esc(t.iosAutoTutorialDesc)}</small></span>${icon('external-link')}`,'ab92-tutorial',busy)}${s.oldIOS?ab92Info(t.iosVersionWarningTitle,t.iosVersionWarningDesc,'triangle-alert'):''}${actionCard(t.iosAutoImportTitle,t.iosAutoImportDesc,'shortcut',t.iosAutoImportButton)}${ab92Info(t.featureDescription,t.iosAutoFeatureDesc)}${ab92Info(t.iosAutoBackTapTitle,t.iosAutoBackTapDesc,'hand')}<article class="ab92-card ab92-manual">${ab92Button('manual',`<b>${esc(t.iosAutoManualConfigTitle)}</b>${icon(s.expanded?'chevron-up':'chevron-down')}`)}${s.expanded?`<div class="ab92-steps"><p>${esc(t.iosAutoManualConfigDesc)}</p><b>${esc(t.iosAutoShortcutConfigTitle)}</b>${Array.from({length:6},(_,i)=>`<div class="ab92-step"><span>${i+1}</span><p>${esc(t['iosAutoShortcutStep'+(i+1)])}</p></div>`).join('')}<p class="ab92-recommend">${esc(t.iosAutoShortcutRecommendedTip)}</p></div>`:''}</article>`;}
 else{body=`${ab92Info(t.featureDescription,t.featureDescriptionContent)}${s.loadError?`<article class="ab92-card ab92-error"><p>${esc(t.commonError)}</p>${ab92Button('retry',esc(t.helpCenterRetry))}</article>`:''}<article class="ab92-card"><div class="ab92-status-row"><span><b>${esc(t.autoBilling)}</b><small>${busy?'…':esc(s.enabled?t.enabled:t.disabled)}</small></span><button class="ab92-switch ${s.enabled?'selected':''}" data-ab92="monitor" role="switch" aria-checked="${s.enabled}" aria-label="${esc(t.autoBilling)}" ${busy||s.loadError?'disabled':''}><i></i></button></div></article><article class="ab92-card"><h3>${icon('battery-charging')}<span>${esc(t.autoBillingBatteryTitle)}</span></h3><p class="${s.healthy&&!s.batteryError?'ab92-healthy':'ab92-warning'}">${busy?'…':esc(s.batteryError?t.commonError:s.healthy?t.reminderBatteryIgnored:t.reminderBatteryNotIgnored)}</p></article>${actionCard(t.autoBillingBatteryGuideTitle,t.autoBillingBatteryDesc,'battery',t.autoBillingCheckBattery,'battery-charging')}`;}
 return `<section class="ab92-page" data-ab92-platform="${s.platform}">${heading}${selector}${body}${ab92Event?`<aside class="ab92-event" role="status">${esc(ab92Event)}</aside>`:''}</section>`;
}
function ab92Battery(){
 if(ab92Data.busy)return;if(ab92Data.batteryError){ab92Event=ab92Texts.commonError;render();return;}
 const t=ab92Texts,s=ab92Data,dialog=document.createElement('dialog');dialog.className='ab92-dialog';dialog.setAttribute('aria-label',t.reminderBatteryStatus);
 dialog.innerHTML=`<h3>${esc(t.reminderBatteryStatus)}</h3><div>${[['reminderManufacturer','QA maker'],['reminderModel','QA device'],['reminderAndroidVersion','QA 17']].map(([key,v])=>'<p>'+esc(ab92Text(key,{manufacturer:v,model:v,version:v}))+'</p>').join('')}<b>${esc(s.healthy?t.reminderBatteryIgnored:t.reminderBatteryNotIgnored)}</b>${!s.healthy?'<p class="ab92-warning">'+esc(t.autoBillingBatteryWarning)+'</p>':''}</div><footer>${!s.healthy&&s.canRequest?ab92Button('battery-settings',esc(t.commonSettings)):''}${ab92Button('battery-confirm',esc(t.commonConfirm))}</footer>`;
 phone.appendChild(dialog);dialog.showModal();globalThis.lucide?.createIcons();const close=()=>{dialog.close();dialog.remove();};dialog.addEventListener('cancel',close);dialog.addEventListener('click',e=>{const action=e.target.closest('[data-ab92]')?.dataset.ab92;if(action==='battery-settings'){s.healthy=true;ab92Event='已调用局部电池设置回调；未请求系统豁免';close();render();}else if(action==='battery-confirm'){close();}});
}
if(typeof window!=='undefined'){
 for(const scene of ab92Fixtures.scenes)fDefine(scene.key,scene.title,'自动记账',scene.data.platform==='ios'?'automation/ios_auto_billing_page.dart':'automation/auto_billing_settings_page.dart',()=>ab92Use(scene.key));
 fDefine('auto-billing-sample','自动记账 · 受控组件','自动记账','presentation/v4/gallery/auto_billing_sample.dart',()=>ab92Use('auto-billing-sample'));
 fDefs['android-auto'].body=()=>ab92Use('auto-billing-android');fDefs['ios-auto'].body=()=>ab92Use('auto-billing-ios');
 const ab92OldRender=fRender;fRender=function(key){return key==='android-auto'||key==='ios-auto'||key.startsWith('auto-billing-')?fDefs[key].body():ab92OldRender(key);};
 const group=document.createElement('optgroup');group.label='自动记账 · 平台与错误';for(const scene of ab92Fixtures.scenes)group.appendChild(new Option(scene.title,'flow-'+scene.key));group.appendChild(new Option('自动记账 · 受控组件','flow-auto-billing-sample'));picker.appendChild(group);
 root.addEventListener('click',e=>{const el=e.target.closest('[data-ab92]');if(!el||el.closest('dialog'))return;e.preventDefault();e.stopImmediatePropagation();const[action,arg]=el.dataset.ab92.split(':');if(action==='monitor')ab92Toggle();else if(action==='retry')ab92Data.loadError=false;else if(action==='manual')ab92Data.expanded=!ab92Data.expanded;else if(action==='shortcut'||action==='tutorial')ab92Open(action);else if(action==='battery'){ab92Battery();return;}else if(action==='platform')ab92Data.platform=arg;else if(action==='old-ios')ab92Data.oldIOS=!ab92Data.oldIOS;render();},true);
 window.beeAutoBillingPreview={get data(){return ab92Copy(ab92Data);},get requests(){return ab92Copy(ab92Requests);}};
}
